module weather_prediction(\n    input clk,\n    input rst_n,\n    input start,\n    input signed [10:0] data_in,\n    input [6:0] n,\n    output reg signed [15:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] READING = 2'd1;\n    localparam [1:0] DONE    = 2'd2;\n\n    reg [1:0] state, next_state;\n    reg [6:0] n_reg;\n    reg [6:0] counter;\n    reg signed [15:0] t0;\n    reg signed [15:0] t1;\n    reg signed [15:0] d;\n    reg signed [15:0] last_temp;\n    reg arithmetic_flag;\n\n    // Sign-extend input\n    wire signed [15:0] current_temp = { {5{data_in[10]}}, data_in };\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 16'd0;\n            n_reg <= 7'd0;\n            counter <= 7'd0;\n            t0 <= 16'd0;\n            t1 <= 16'd0;\n            d <= 16'd0;\n            last_temp <= 16'd0;\n            arithmetic_flag <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= READING;\n                        n_reg <= n;\n                        counter <= 7'd0;\n                        arithmetic_flag <= 1'b1;\n                    end\n                end\n\n                READING: begin\n                    case (counter)\n                        7'd0: begin\n                            t0 <= current_temp;\n                            last_temp <= current_temp;\n                        end\n                        7'd1: begin\n                            t1 <= current_temp;\n                            d <= t1 - t0;\n                            last_temp <= current_temp;\n                        end\n                        default: begin\n                            if ((current_temp - last_temp) != d) arithmetic_flag <= 1'b0;\n                            last_temp <= current_temp;\n                        end\n                    endcase\n\n                    if (counter == n_reg - 7'd1) begin\n                        state <= DONE;\n                    end\n                    counter <= counter + 7'd1;\n                end\n\n                DONE: begin\n                    if (arithmetic_flag) result <= last_temp + d;\n                    else result <= last_temp;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule